import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

function idOf(raw: string): string {
  if (typeof raw !== 'string' || !/^\d{1,18}$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '알림 ID 형식이 올바르지 않습니다.');
  }
  return raw;
}

@Controller('api/v1')
export class FnSfr02802Controller {
  @Get('/notifications/:notificationId')
  async getNotification(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = idOf(req.params['notificationId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `UPDATE notification
            SET read_yn = true,
                read_at = now(),
                updated_at = now()
          WHERE notification_id = CAST(:notificationId AS bigint)
            AND employee_id = CAST(:userId AS bigint)
      RETURNING notification_id AS "notificationId",
                title AS "title",
                summary AS "summary",
                detail AS "detail",
                target_type AS "targetType",
                target_id AS "targetId",
                read_yn AS "readYn",
                occurred_at AS "occurredAt"`,
        { notificationId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '해당 알림을 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Get('/notifications/:notificationId/shortcut')
  async getNotificationShortcut(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const notificationId = idOf(req.params['notificationId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT target_type AS "targetType",
                target_id AS "targetId"
           FROM notification
          WHERE notification_id = CAST(:notificationId AS bigint)
            AND employee_id = CAST(:userId AS bigint)`,
        { notificationId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NOTIFICATION_NOT_FOUND', '해당 알림을 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

