import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  Select,
  DateInput,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const PAGE_SIZE = 20;

export default function FnSfr02802Page({ role, notify }: PageProps) {
  const [typeDraft, setTypeDraft] = useState('');
  const [fromDraft, setFromDraft] = useState('');
  const [toDraft, setToDraft] = useState('');
  const [type, setType] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [dateError, setDateError] = useState('');
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | undefined>(undefined);
  const [shortcut, setShortcut] = useState<Row | undefined>(undefined);

  const list = useData<Page>(
    () => call<Page>('GET', '/notifications', role, undefined, { notificationType: type, page: 0, size: 200 }),
    [type, role],
  );

  const all = list.data?.items ?? [];
  const rows = all.filter((r) => {
    const day = String(r.occurredAt ?? '').slice(0, 10);
    if (from && day < from) return false;
    if (to && day > to) return false;
    return true;
  });
  const unread = rows.filter((r) => !r.readYn);
  const paged = rows.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  const search = () => {
    if (fromDraft && toDraft && fromDraft > toDraft) {
      setDateError('조회 시작일이 종료일보다 늦습니다.');
      return;
    }
    setDateError('');
    setType(typeDraft);
    setFrom(fromDraft);
    setTo(toDraft);
    setPage(0);
  };

  const reset = () => {
    setDateError('');
    setTypeDraft('');
    setFromDraft('');
    setToDraft('');
    setType('');
    setFrom('');
    setTo('');
    setPage(0);
  };

  const open = async (row: Row) => {
    try {
      const d = await call('GET', '/notifications/' + String(row.notificationId), role);
      setShortcut(undefined);
      setDetail(d);
      list.reload();
    } catch (e) {
      notify(e instanceof Error ? e.message : '알림을 불러오지 못했습니다.');
    }
  };

  const goShortcut = async () => {
    if (!detail) return;
    const s = await call('GET', '/notifications/' + String(detail.notificationId) + '/shortcut', role);
    setShortcut(s);
    notify('바로가기 대상을 확인했습니다.');
  };

  const columns = [
    { key: 'notificationType', label: '알림 구분', render: (r: Row) => <Badge value={r.notificationType} /> },
    { key: 'title', label: '제목' },
    { key: 'summary', label: '요약' },
    { key: 'readYn', label: '읽음 여부', render: (r: Row) => <Badge value={r.readYn ? '읽음' : '대기'} /> },
    { key: 'occurredAt', label: '이벤트 발생 일시', render: (r: Row) => <DateText value={r.occurredAt} time /> },
  ];

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>알림 현황</h2>
        <Tiles items={[['전체 알림', rows.length], ['읽지 않은 알림', unread.length]]} />
      </section>

      <section className='box span-8'>
        <h2>통합 알림</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='알림 구분'>
            <Select
              value={typeDraft}
              onChange={setTypeDraft}
              options={[['ALERT', '알림'], ['MENTION', '@멘션']]}
              placeholder='전체'
            />
          </Field>
          <Field label='조회 시작일'>
            <DateInput value={fromDraft} onChange={setFromDraft} />
          </Field>
          <Field label='조회 종료일'>
            <DateInput value={toDraft} onChange={setToDraft} />
          </Field>
        </Filters>
        {dateError ? <ErrorText text={dateError} /> : null}
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={rows.length} />
        <DataTable columns={columns} rows={paged} onRowClick={open} empty='알림이 없습니다.' />
        <Pager page={page} size={PAGE_SIZE} total={rows.length} onPage={setPage} />
      </section>

      <section className='box span-4'>
        <h2>읽지 않은 알림</h2>
        <DataTable
          columns={[
            { key: 'title', label: '제목' },
            { key: 'occurredAt', label: '발생 일시', render: (r: Row) => <DateText value={r.occurredAt} time /> },
          ]}
          rows={unread.slice(0, 5)}
          onRowClick={open}
          empty='읽지 않은 알림이 없습니다.'
        />
      </section>

      {detail ? (
        <Drawer title='알림 상세' onClose={() => setDetail(undefined)}>
          <Pairs
            items={[
              ['제목', String(detail.title ?? '')],
              ['요약', String(detail.summary ?? '')],
              ['상세내용', String(detail.detail ?? '')],
              ['바로가기 대상 유형', String(detail.targetType ?? '')],
              ['바로가기 대상 식별자', String(detail.targetId ?? '')],
              ['읽음 여부', <Badge value={detail.readYn ? '읽음' : '대기'} />],
              ['이벤트 발생 일시', <DateText value={detail.occurredAt} time />],
            ]}
          />
          {shortcut ? (
            <Pairs
              items={[
                ['이동 대상 유형', String(shortcut.targetType ?? '')],
                ['이동 대상 식별자', String(shortcut.targetId ?? '')],
              ]}
            />
          ) : null}
          <Form onSubmit={goShortcut} submit='바로가기' />
        </Drawer>
      ) : null}
    </div>
  );
}
